# Kaggle script kernel: safety-mechanism parity + draft 19 + stale float alpha.
import base64, subprocess, sys
payload = {'deterministic_mode_parity.py': '', 'safety_mechanisms_lost.py': '', 'float_arg_cache_matrix.py': '', 'draft19.py': ''}
for n, b in payload.items():
    open(n, 'wb').write(base64.b64decode(b))
for spec in [["--upgrade", "torch==2.14.0"]]:
    subprocess.run(["pip", "-q", "install", *spec])
    for n in payload:
        print('=====', n, flush=True)
        subprocess.run([sys.executable, n])
print("JOB DONE", flush=True)
